INSERT INTO public.other_points (title, description, last_updated, geom, hub_id, kind) VALUES ('800 meter ny sti på Heiå', '120 m ny natursteinsti (Årstein Lima, Gjesdal Bygdeservice), 300 m nyopna sti gjennom tett skog, resten nymerka inn til gamle stiar. Gir alternativ sti rundt beitande kyr. Dugnad: Per Einar Lillejordet, Bjørn Ove Modalsli, Nina Svensen, Milrid Aarsland og Arne Kulander. Støtte frå Sparebankstiftelsen SR-Bank.', '2026-09-26', ST_SetSRID(ST_MakePoint(5.8272172, 58.7460482), 4326), 5, 'nysti');
INSERT INTO public.gjerdeklyvere (title, description, last_updated, geom, hub_id) VALUES ('To ombygde gjerdeklyvarar på Vardafjell', 'To gamle gjerdeklyvarar bygde om – betre, enklare og sikrare, og no også mulege å bruka for hundar. Arbeid: Finn Helge Lima og Erling Gundersen.', '2026-08-24', ST_SetSRID(ST_MakePoint(5.8815061, 58.7913096), 4326), 10);
INSERT INTO public.other_points (title, description, last_updated, geom, hub_id, kind) VALUES ('Steinbru (klopp) over Kvernhusbekken i Trodalen', 'Ny steinbru/klopp over Kvernhusbekken, laga med gravemaskin av Eirik P. Håland. I samarbeid med grunneigar for å redusera konflikt med storfe på beite. Støtte frå Sparebankstiftelsen SR-Bank.', NULL, ST_SetSRID(ST_MakePoint(5.8262172, 58.7460482), 4326), 5, 'drenering');
INSERT INTO public.other_points (title, description, last_updated, geom, hub_id, kind) VALUES ('120 m natursteinsti i Trodalen', 'Om lag 120 m stibygging med naturstein, inkludert tre grøftekryssingar (Årstein Lima, Gjesdal Bygdeservice). Raudmerka heilårsstiar vidare mot Høga Håland/Hålandsskogen, Riset/Eikeland skule, Gunnhildtjørna/Heiå/Bukkatonå/Bursfjellet og Litle Bursfjellet.', NULL, ST_SetSRID(ST_MakePoint(5.8257172, 58.7456151), 4326), 5, 'nysti');
INSERT INTO public.other_points (title, description, last_updated, geom, hub_id, kind) VALUES ('Stiforbetring på Refnes', 'Snautt 50 m sti forbetra: drensrøyr, steinsett ytterkant, oppbygging med steinstøv og meir treflis. Steinstøv frå Bjelland, treflis frå Sigmundsen Transport.', '2026-07-21', ST_SetSRID(ST_MakePoint(5.8284624, 58.7626809), 4326), 6, 'drenering');
INSERT INTO public.other_points (title, description, last_updated, geom, hub_id, kind) VALUES ('Steinstøv på 200 m sti på Refnes (dugnad)', 'Om lag 200 m sti skal få eit lag steinstøv. Open dugnad – spade, trillebåre og rive ligg klar ved haugen. Steinstøv frå Bjelland AS.', '2026-07-23', ST_SetSRID(ST_MakePoint(5.8274625, 58.7626809), 4326), 6, 'grus');
INSERT INTO public.other_points (title, description, last_updated, geom, hub_id, kind) VALUES ('Tilrettelegging for hjulgåande hjelpemiddel i Fiskebekkdalen', 'Ny port, røyr lagt ned i bekken og ny turveg bygd opp med stein, singel og steinstøv, tilpassa rullestol og liknande. Arbeid: Paul Moi, Kåre Taksdal og Erling Gundersen. Material frå Obs Bygg Ålgård, singel/steinstøv frå Bjelland AS, gravemaskin frå Årstein Lima (Gjesdal Bygdeservice). Liknande vart gjort i Kodlidalen i vinter.', NULL, ST_SetSRID(ST_MakePoint(5.8805061, 58.7913096), 4326), 10, 'grus');
INSERT INTO public.other_points (title, description, last_updated, geom, hub_id, kind) VALUES ('Nytt parkeringsskilt på Auestad', 'Nytt skilt ved parkeringsplassen på Auestad. Ikkje lov å parkera ved grustaket forbi kyllinghuset. Skiltmontering: Paul Moi.', '2026-07-17', ST_SetSRID(ST_MakePoint(5.9068500, 58.7513630), 4326), 8, 'turinfo');
INSERT INTO public.other_points (title, description, last_updated, geom, hub_id, kind) VALUES ('Ny parkeringsplass på Fjermestad', 'Ny parkeringsplass der rundballane før stod, for turar rundt Refnes og Øygardsvatnet. Open 08–22, Vipps 50 kr. Økonomisk bidrag frå Time kommune, bautastein frå Skurve Maskin AS.', NULL, ST_SetSRID(ST_MakePoint(5.8269624, 58.7622479), 4326), 6, 'annet');
INSERT INTO public.other_points (title, description, last_updated, geom, hub_id, kind) VALUES ('Betre P-plass på veg til Sikvalandskula', 'Parkeringsplassen oppgradert med eit par tonn steinstøv i overgangen mot asfaltvegen. Arbeid: Kåre Taksdal. Massar frå Bjelland AS.', NULL, ST_SetSRID(ST_MakePoint(5.9058500, 58.7513630), 4326), 8, 'grus');
